def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    my = tuple(h[0] for h in history)
    op = tuple(h[1] for h in history)

    op_c = op.count('C')
    my_c = my.count('C')
    op_d = n - op_c
    my_d = n - my_c

    if op_c == 0:
        return 'D'

    run_op_d = 0
    for x in reversed(op):
        if x == 'D':
            run_op_d += 1
        else:
            break

    d8 = op[-8:].count('D')
    d16 = op[-16:].count('D')

    after_my_d = 0
    forgiven = 0
    punished = 0
    opp_d_after_my_c = 0

    for i in range(1, n):
        if my[i - 1] == 'C':
            if op[i] == 'D':
                opp_d_after_my_c += 1
        else:
            after_my_d += 1
            if op[i] == 'C':
                forgiven += 1
            else:
                punished += 1

    last_my = my[-1]
    last_opp = op[-1]

    if run_op_d >= 4 or d8 >= 7 or d16 >= 10:
        return 'D'

    if op_d * 3 > n and (run_op_d >= 1 or opp_d_after_my_c >= max(1, n // 5)):
        return 'D'

    if my_d == 0 and op_d == 0 and n == 15:
        return 'D'
    if my_d == 0 and op_d <= 1 and run_op_d == 0 and n == 35:
        return 'D'

    exploitable = (
        after_my_d > 0 and
        forgiven > punished and
        op_d * 2 <= n and
        d16 <= 10 and
        run_op_d <= 2
    )

    if last_opp == 'D':
        if run_op_d >= 2:
            return 'D'
        if last_my == 'D':
            return 'C'
        if exploitable:
            return 'D'
        if punished > 0 and forgiven == 0 and op_d <= max(5, n // 4):
            return 'C'
        return 'D'

    if last_my == 'D' and after_my_d == 0:
        return 'C'
    if exploitable:
        return 'D'
    return 'C'
